// Builders for the transcript lines a guard `canary` feeds its guard.
//
// A canary transcript is written as raw nested object literals, and a guard
// needing a tool call plus its result costs ~20 lines of that shape — enough to
// push `registry.ts` past its `max-lines` cap. These builders keep a canary
// legible at one line per transcript line.
//
// Deliberately dependency-free and type-loose: `registry.ts` must stay lazy with
// respect to guard modules, so nothing here may reach one, and the canary field
// is structurally typed rather than nominally.

/** A real user prompt — the boundary turn extraction slices on. */
export function userPromptLine(content: string): Record<string, unknown> {
  return { type: "user", message: { role: "user", content } };
}

/** An assistant line carrying one `tool_use` block. */
export function toolUseLine(
  id: string,
  name: string,
  input: Record<string, unknown>
): Record<string, unknown> {
  return {
    type: "assistant",
    message: { role: "assistant", content: [{ type: "tool_use", id, name, input }] },
  };
}

/** The user-role line carrying a `tool_result` correlated to `toolUseId`. */
export function toolResultLine(toolUseId: string, content: string): Record<string, unknown> {
  return {
    type: "user",
    message: {
      role: "user",
      content: [{ type: "tool_result", tool_use_id: toolUseId, content }],
    },
  };
}

/** An assistant line carrying one plain `text` block. */
export function assistantTextLine(text: string): Record<string, unknown> {
  return { type: "assistant", message: { role: "assistant", content: [{ type: "text", text }] } };
}
